    g_dsfs : as_FSB H <= ds /\ ds + DS_SIZE <= as_FSB H + AFS_SIZE;
    g_err : - 2 ^ 31 <= err < 0;
    g_hw : hw mod 2 = 1 /\ 0 <= hw < 2 ^ 64 /\ AIMG_TOP <= dptr < 2 ^ 47;
    g_f : aframe_range H 2 ff fp /\ afsb_ok H;
    g_fds : (ff + 256 <= ds \/ ds + DS_SIZE <= ff) /\ (fp + 1 <= ds \/ ds + DS_SIZE <= fp)
