  }.

  Record dsr (m : mem) : Prop := DSR {
    r_16 : rw_cells asegs m (ds + 16) [C8 (Z_to_bv 64 LOC_IMP_A)];
    r_160 : rw_cells asegs m (ds + 160) [C8 (Z_to_bv 64 LOC_IMP_A)];
    r_168 : rw_cells asegs m (ds + 168) [C8 (Z_to_bv 64 0)];
    r_176 : rw_cells asegs m (ds + 176) [C8 (Z_to_bv 64 0)];
    r_184 : rw_cells asegs m (ds + 184) [C8 (Z_to_bv 64 0)];
    r_200 : rw_cells asegs m (ds + 200) [C8 (Z_to_bv 64 0)];
    r_224 : rw_cells asegs m (ds + 224) [C8 (Z_to_bv 64 0)];
    r_320 : rw_cells asegs m (ds + 320) [C8 (Z_to_bv 64 0)];
    r_336 : rw_cells asegs m (ds + 336) [C1 (b8 (bv_unsigned (Z_to_bv 64 0)))];
    r_360 : rw_cells asegs m (ds + 360) [C4 (Z_to_bv 64 (err mod 2 ^ 32))];
    r_368 : rw_cells asegs m (ds + 368) [C1 (b8 (bv_unsigned (Z_to_bv 64 0)))]
  }.

  Definition hdrf (h : nat) (m : mem) : Prop :=
    match h with
    | O => True
    | S O => rw_cells asegs m (ds + 72) [C1 (b8 (bv_unsigned (Z_to_bv 64 44)))]
    | _ => rw_cells asegs m (ds + 72) [C8 (Z_to_bv 64 hw)] /\ rw_cells asegs m (ds + 88) [C8 (Z_to_bv 64 dptr)]
    end.

  Record df (h : nat) (m : mem) : Prop := DF {
    q_ac : ACONST m;
    q_lv : LINV_P5 m;
    q_stk : stk asegs m lo spz;
    q_dsa : addressable m ds DS_SIZE;
    q_dsw : wr_at asegs m ds DS_SIZE;
    q_dsv : shvis m ds (ds + DS_SIZE);
    q_dsr : dsr m;
    q_hdr : hdrf h m;
    q_fw : wr_at asegs m ff 256;
    q_hw : wr_at asegs m (sh ff) 32;
    q_lw : wr_at asegs m fp 1
  }.
End Bundles.

