    /\ AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil
    /\ (as_FSB H + AFS_SIZE <= ALOWSH_LO \/ AHI_LO <= as_FSB H)
    /\ 0x7fff7f800000 <= aceil <= 0x7fffff800000
    /\ AIMG_TOP <= ds /\ (ds + DS_SIZE <= ALOWSH_LO \/ AHI_LO <= ds) /\ ds + DS_SIZE + 64 <= AAPP_HI /\ ds + DS_SIZE <= aceil /\ ds mod 8 = 0
    /\ - 2 ^ 31 <= err < 0 /\ (hw mod 2 = 1 /\ 0 <= hw < 2 ^ 64 /\ AIMG_TOP <= dptr < 2 ^ 47)
    /\ aceil <= lo /\ lo <= spz - ADS_STACK.
