  Lemma tabs_okd6 : forall h m0 m XT AT D0T D1T FT HT ks1 ks2 ks3 ks4 ks5 ks6, df h m0 /\ Dx m0 m -> mem_inv asegs m ->
    ftbl WD spz m XT -> ftbl WD spa m AT -> ftbl WD ds m D0T -> ftbl WD ds m D1T -> ftbl WD ff m FT -> ftbl WD (ff / 8) m HT ->
    fin (-104) 0 ks1 = true -> fin (-48) 88 ks2 = true -> fin 0 16 ks3 = true -> fin 112 120 ks4 = true -> fin 0 256 ks5 = true ->
    fin SHBASE (SHBASE + 32) ks6 = true ->
